  var HELP = {
    spread: ['Spread', __esT_mpheatmap("theGapBetweenThe",'The gap between the best price a buyer will pay and the cheapest a seller will take. Cross it and you pay it: it is the toll for wanting something right now instead of waiting. On a busy coin it is a hundredth of a percent; on a quiet one it can be ten times that.')],
    bps: ['Basis points (bps)', __esT_mpheatmap("aHundredthOfOne",'A hundredth of one percent. 1 bps = 0.01%, 100 bps = 1%. Traders use it because "the spread moved from 0.01% to 0.02%" is a mouthful, while "1 to 2 bps" is not.')],
    resting: [__esT_mpheatmap("restingOrders",'Resting orders'), __esT_mpheatmap("moneySittingInThe",'Money sitting in the order book at a chosen price, waiting. Nobody has spent it yet, and it can be pulled at any second - which is exactly why a wall held by one exchange alone is less trustworthy than the same wall shared by four.')],
    rowstep: [__esT_mpheatmap('rowStepT', 'Row height'), __esT_mpheatmap('rowStepB', 'How much price ONE line of the ladder covers. Five exchanges quote to a fraction of a cent, so their orders are added up into rows of this size - pick a bigger row and the small orders in between merge into the walls, which is how you see where the real money is instead of forty lines of dust. Nothing is hidden: a bigger row holds more, never less. The running total beside it always counts everything, whichever row height you choose.')],
    bookfilm: [__esT_mpheatmap('bookFilmT', 'The book over time'), __esT_mpheatmap('bookFilmB', 'The panel above is a photograph of the order book; this is the film of it. Price runs down the side, time runs across, and the colour is how many dollars were waiting at that price at that moment - green waiting to buy, red waiting to sell. It answers the three things one snapshot cannot: how LONG a wall has been standing, whether it is held by one exchange or by all five, and what happened to the walls that are gone - traded through, or simply withdrawn. Resting orders are a fact about right now, never a promise: they can be cancelled in a second.')],
    sum: ['Sum', __esT_mpheatmap("theRunningTotalAs",'The running total as you walk away from the price. The row three ticks down does not show what sits at that price alone - it shows everything between the current price and there, so it answers "how much would I have to eat through to get that far".')],
    venuestrip: [__esT_mpheatmap("whoHoldsIt",'Who holds it'), __esT_mpheatmap("theThinColouredLine",'The thin coloured line under each row, split by exchange. One colour means a single venue is holding that price on its own; four colours mean four books agree. A wall nobody else supports can disappear between two blinks.')],
    aggressor: ['Aggressor', __esT_mpheatmap("everyTradeHasA",'Every trade has a patient side and an impatient one. Whoever crossed the spread to make it happen is the aggressor: an arrow up means a buyer paid the asking price, an arrow down means a seller accepted the bid. The candle records the price; only the tape records who was in a hurry.')],
    slippage: ['Slippage', __esT_mpheatmap("aLargeOrderEats",'A large order eats the best price first, then the next, then the next - so the average price it actually gets is worse than the one on screen. This is that difference, measured by walking our real book, not estimated.')],
    netflow: ['Net flow', __esT_mpheatmap("aggressiveBuyingMinusAggre",'Aggressive buying minus aggressive selling, in dollars, over the last few minutes. Positive means buyers were the impatient ones. Read it against the price: price grinding up while sellers are the aggressors means somebody is quietly absorbing them.')],
    bigprint: ['Bright rows', __esT_mpheatmap("aTradeFarLarger",'A trade far larger than the rest of what is on screen - eight times the middle-sized print. Size alone does not predict anything, but a cluster of them on one side, at one price, is the market telling you where somebody with real money is working.')],
    tick: [__esT_mpheatmap("rowsOf",'Rows of'), __esT_mpheatmap("howWideEachRow",'How wide each row of the book is in price. Five exchanges quote to a fraction of a cent, so their prices are grouped into rows of this size - otherwise the ladder would be forty rows of dust instead of eight rows of size.')],
    lined: [__esT_mpheatmap("linedUp",'Lined up'), __esT_mpheatmap("exchangesDoNotTrade",'Exchanges do not trade at exactly the same price - measured on Bitcoin, one venue sat $73 above the other four. When you look at all of them together each book is shifted onto the shared middle price first, so a row means "this far from the price" rather than a number that crosses itself.')],
    zone: ['Liquidation zone', __esT_mpheatmap("aPriceWhereA",'A price where a crowd of leveraged positions would be force-closed. It is a MODEL, not a record: the exchange never publishes who is leveraged where, so this is estimated from price history. Price is often pulled toward the heavy ones, because a forced close is an order that has to happen.')],
    crowded: ['How crowded', 'The column beside the map ranks each level against the OTHERS YOU CAN SEE, not against a dollar amount. 2.3x means we estimate roughly twice as many leveraged traders would be closed out at that price as at an average level on this screen; 0.8x means fewer than average. It is a comparison on purpose - exchanges never publish who is leveraged where, so a dollar figure there would be invented. Use it to rank the levels in front of you, and trust the measured 24h figure in the tooltip when the two disagree.'],
    targets: ['Targets', __esT_mpheatmap("theNearestModelledLiquidat",'The nearest modelled liquidation zones above and below the price - the same crowds the column beside the map ranks - green where longs get closed out, red where shorts do. Tap one to show it on the map. They are estimates from price history, never a record of money that has changed hands.')],
    costmove: [__esT_mpheatmap("whatItCostsTo",'What it costs to move it'), __esT_mpheatmap("theDollarsOfResting",'The dollars of resting orders inside a tenth of a percent of the price. To lift the price that far, a buyer has to eat all of them - so this is the price of moving the market, in the only unit anybody thinks in. When one side is far cheaper than the other, that is the direction of least resistance right now. It is a fact about the book this second, not a forecast: the orders can be pulled.')],
    measured: [__esT_mpheatmap("measuredNotModelled",'Measured, not modelled'), __esT_mpheatmap("everythingInThisPanel",'Everything in this panel is something that really exists right now: orders standing in five books, trades that really printed. The map above it is a model of where leverage probably sits. We keep the two apart on purpose, and never put a dollar figure on the model.')],
  };
  var _hq = null;
  function helpClose() { if (_hq) { _hq.remove(); _hq = null; } }
  function helpOpen(btn) {
    helpClose();
    var e = HELP[btn.getAttribute('data-q')];
    if (!e) return;
    var d = document.createElement('div');
    d.className = 'hm-qc';
    d.innerHTML = '<b>' + e[0] + '</b><span>' + e[1] + '</span>';
    document.body.appendChild(d);
    var r = btn.getBoundingClientRect(), w = Math.min(300, innerWidth - 24);
    d.style.width = w + 'px';
    var left = Math.max(12, Math.min(innerWidth - w - 12, r.left + r.width / 2 - w / 2));
    var top = r.bottom + 8, hh = d.getBoundingClientRect().height;
    if (top + hh > innerHeight - 8) top = Math.max(8, r.top - hh - 8);
    d.style.left = (left + scrollX) + 'px'; d.style.top = (top + scrollY) + 'px';
    _hq = d;
  }
  // ONE listener for the whole page. Hover on a real pointer, tap on a touch screen - and a tap must not
  // also fire the thing behind it, which on a Targets chip would move the map while trying to read a word.
  (function () {
    var coarse = false; try { coarse = matchMedia('(pointer:coarse)').matches; } catch (e) {}
    document.addEventListener('click', function (ev) {
      var b = ev.target.closest && ev.target.closest('.hm-q');
      if (b) { ev.preventDefault(); ev.stopPropagation(); if (_hq && _hq._for === b) helpClose(); else { helpOpen(b); if (_hq) _hq._for = b; } return; }
      if (!ev.target.closest || !ev.target.closest('.hm-qc')) helpClose();
    }, true);
    if (!coarse) {
      document.addEventListener('mouseover', function (ev) {
        var b = ev.target.closest && ev.target.closest('.hm-q');
        if (b) { helpOpen(b); if (_hq) _hq._for = b; }
        else if (_hq && !(ev.target.closest && ev.target.closest('.hm-qc'))) helpClose();
      });
    }
    addEventListener('scroll', helpClose, { passive: true });
    addEventListener('keydown', function (ev) { if (ev.key === 'Escape') helpClose(); });
  })();
  function q(key) { return '<b class="hm-q" data-q="' + key + '" role="button" tabindex="0" aria-label="What is this?">?</b>'; }

// ---- FILTERS, ONE PER COLUMN, IN THE HEADER OF THE THING THEY CONTROL (2026-09-22) ------------------
// Owner: "neki cool filter za tape i book, tipa da se izabere koji je minimalan iznos koji hocu da vidim".
//
// The TAPE gets exactly that: a floor in dollars, so a reader can throw away the hundreds of $87 prints
// that make a busy coin unreadable and watch only orders with money behind them. It is the same idea the
// map's own liquidation-dot filter already uses, and the same ladder of sizes, so the page is consistent.
//
// THE BOOK DOES NOT GET A SIZE FILTER, and that is deliberate: a ladder has to be CONTIGUOUS to mean
// anything - Sum is the running total as you walk away from the price, and hiding the small rows in the
// middle would silently break every number below them. What a book is filtered by is its ROW WIDTH, which
// is what the "0.1" control on an exchange terminal does: group the same orders more coarsely and the
// small stuff merges into the walls instead of disappearing. Nothing is hidden; it is aggregated.
//
// Both persist, because a reader who wants $50k+ wants it on every visit, and both say what they are
// doing next to the control - a filter you cannot see is a filter that makes the page look broken.
var TPMIN = [['0', 'All prints'], ['1000', '$1K+'], ['10000', '$10K+'], ['50000', '$50K+'], ['250000', '$250K+'], ['1000000', '$1M+'], ['2000000', '$2M+'], ['5000000', '$5M+'], ['10000000', '$10M+'], ['20000000', '$20M+']];
var TICKX = [['1', 'Auto'], ['2', 'x2'], ['5', 'x5'], ['10', 'x10'], ['25', 'x25']];
function bkPref(k, d) { try { var v = localStorage.getItem(k); return v == null ? d : +v; } catch (e) { return d; } }
function bkPrefSet(k, v) { try { localStorage.setItem(k, String(v)); } catch (e) {} }
function bkSelect(cls, opts, cur) {
  var h = '<select class="hm-mini ' + cls + '">';
  for (var i = 0; i < opts.length; i++) h += '<option value="' + opts[i][0] + '"' + (+opts[i][0] === +cur ? ' selected' : '') + '>' + opts[i][1] + '</option>';
  return h + '</select>';
}

